    private static String textOf(Locator locator, String label) {
        try {
            return locator.isVisible() ? locator.innerText() : null;
        } catch (PlaywrightException e) {
            WaitActions.throwIfDefect(e, label);
            return null;
        }
    }

    private static String valueOf(Locator locator, String label) {
        try {
            if (!locator.isVisible()) return null;
            // A dropdown holds the option it shows, by its words, as choose() picks it.
            return String.valueOf(locator.evaluate("e => e.tagName === 'SELECT' ? (e.selectedOptions[0] ? e.selectedOptions[0].text : '') : e.value"));
        } catch (PlaywrightException e) {
            WaitActions.throwIfDefect(e, label);
            return null;
        }
    }

