    /** What the attribute was, for a failure: its value, "missing", or "not shown". */
    private static String attribute(Locator locator, String name, String label) {
        try {
            if (!locator.isVisible()) return "nothing (it was not shown)";
            String value = locator.getAttribute(name);
            return value == null ? "missing" : "\"" + value + "\"";
        } catch (PlaywrightException e) {
            WaitActions.throwIfDefect(e, label);
            return "nothing (it was not shown)";
        }
    }

    /** "not shown" while it was not shown, otherwise the word for the state it was in. */
    private static String state(Boolean shown, String otherwise) {
        return shown == null ? "not shown" : otherwise;
    }

    private static String quoted(String text) {
        return text == null ? "nothing (it was not shown)" : "\"" + text.trim() + "\"";
    }

    /** A link with this href as written is shown. */
    private static boolean linkShown(Page page, String href) {
        return countOf(page.locator("xpath=//a[@href=" + Headings.literal(href) + "]").locator("visible=true"), "the link to " + href) > 0;
    }

    /** The script that reads the page around a control (the same in every framework Suite Builder writes). */
    private static final String AROUND_IT = "(function (xpath, doc) {\n  var d = doc || document;\n  var el = d.evaluate(xpath, d, null, 9, null).singleNodeValue;\n  if (!el) return null;\n  var parent = el.parentElement;\n  var box = (parent && parent.closest(\"section, nav, header, aside, footer, [role=region], [role=navigation], [aria-roledescription], [class*=carousel], [class*=slider], [class*=swiper], [class*=accordion], [class*=menu], [class*=dropdown]\")) || parent || el;\n  return box.outerHTML + \"\\u0000\" + el.outerHTML + \"\\u0000\" + (d.body ? d.body.className : \"\");\n})";

    /** The page around the control, as text to compare; null when the control is not there. */
    private static String aroundIt(Page page, String xpath) {
        try {
            return (String) page.evaluate(AROUND_IT, xpath);
        } catch (PlaywrightException e) {
            return null;
        }
    }

    private static void clickXPath(Page page, String xpath) {
        page.locator("xpath=" + xpath + " >> visible=true").first().click();
    }

    private static String waited() {
        long waited = WaitActions.elementTimeout();
        return " (waited " + (waited % 1000 == 0 ? String.valueOf(waited / 1000) : String.valueOf(waited / 1000.0)) + " s).";
    }

    private static void fail(String message) {
        throw new AssertionError(message);
    }

    /** What a test needed was not there (assume): RerunOnce skips the test with its reason, and tries it no more. */
    public static final class NotMet extends RuntimeException {
        private static final long serialVersionUID = 1L;

        NotMet(String why) {
            super(why);
        }
    }

    /** A locator found on the fly, as a PageElement. */
    private record Found(Locator locator, String label) implements PageElement {
        @Override
        public Locator locator(Page page) {
            return locator;
        }

        @Override
        public String name() {
            return label;
        }
    }

